import os
import tempfile
import unittest

from spacefractions.persistence import connect, init_db
from spacefractions.question.repository import QuestionRepository


class PersistenceTest(unittest.TestCase):
    def test_schema_created(self):
        conn = connect(":memory:")
        try:
            init_db(conn)
            cur = conn.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = {row[0] for row in cur.fetchall()}
            self.assertTrue({"games", "questions", "users", "admins"}.issubset(tables))
        finally:
            conn.close()

    def test_data_durable_across_reopen(self):
        with tempfile.TemporaryDirectory() as directory:
            path = os.path.join(directory, "spacefractions.db")
            conn = connect(path)
            init_db(conn)
            QuestionRepository(conn).add("1/2 + 1/2", ["1", "2"], 0)
            conn.close()

            conn2 = connect(path)
            init_db(conn2)
            try:
                self.assertEqual(QuestionRepository(conn2).count(), 1)
            finally:
                conn2.close()


if __name__ == "__main__":
    unittest.main()
